package com.example.riskflow;

import com.example.riskflow.event.*;
import com.example.riskflow.generated.PricingDag;
import com.telamin.fluxtion.runtime.DataFlow;
import com.telamin.fluxtion.runtime.connector.DataFlowConnector;
import com.telamin.fluxtion.runtime.connector.FileMessageSink;
import com.telamin.fluxtion.runtime.connector.InMemoryEventFeed;
import com.telamin.fluxtion.runtime.output.MessageSink;
import org.agrona.concurrent.SleepingMillisIdleStrategy;

/**
 * Entry point — generated by the Fluxtion project starter (DataFlowConnector host).
 * The connector hosts the graph *however it was generated* (imperative @OnEventHandler or DSL
 * subscribe): the feeds publish events, the connector routes each to the graph, and the graph's own
 * dispatch handles them. In-memory feeds broadcast the raw event; file feeds deliver each line as a
 * String. Sinks receive whatever the graph publishes to "output".
 */
public final class FluxtionMain {

    public static void main(String[] args) throws Exception {
        // AOT: the generated processor (the shell is overwritten by './mvnw package').
        DataFlow flow = new PricingDag();
        flow.init();
        // Surface any event that reaches no @OnEventHandler — handy while wiring a new graph.
        flow.setUnKnownEventHandler(e -> System.out.println(
                "unhandled event (no @OnEventHandler matched — add a handler or a feed valueMapper): " + e));
        // Print audit records to stdout — the default java.util.logging sink is invisible in the
        // Playground console, so an audited graph would otherwise look idle.
        flow.setAuditLogProcessor(logRecord -> System.out.println(logRecord));

        InMemoryEventFeed pricesFeed = new InMemoryEventFeed("prices", false, true);
        pricesFeed.setWrapEvent(false);
        InMemoryEventFeed ordersFeed = new InMemoryEventFeed("orders", false, true);
        ordersFeed.setWrapEvent(false);
        MessageSink<Object> alertsSink = message -> System.out.println("alerts: " + message);
        FileMessageSink auditSink = new FileMessageSink("data/audit.txt");
        // Queue the sample events into the in-memory feed(s) BEFORE starting, so the agent reads them on
        // its first poll (the feed reads EARLIEST). This mirrors a file feed, whose data is already
        // present when the agent runs, which is the shape that dispatches reliably under CheerpJ.
        pricesFeed.publish(new PriceUpdate());
        pricesFeed.publish(new OrderEvent());
        ordersFeed.publish(new PriceUpdate());
        ordersFeed.publish(new OrderEvent());

        DataFlowConnector connector = new DataFlowConnector(new SleepingMillisIdleStrategy(1));
        connector
                .addFeed(pricesFeed)
                .addFeed(ordersFeed)
                .addDataFlow(flow)
                .addSink("alerts", alertsSink)
                .addSink("audit", auditSink)
                .start();

        // Let the agent thread poll the feeds and dispatch. Use a LOOP of short sleeps, not one long
        // sleep: each sleep yields cooperatively, which is what gives the background agent CPU under
        // CheerpJ in the browser. A single Thread.sleep(1500) starves the agent there, so events are
        // never dispatched (no sinks, no audit). Same pattern DataFlowConnector.start() uses.
        for (int i = 0; i < 300; i++) {
            Thread.sleep(5);
        }
        connector.stop();
        System.out.println("FluxtionMain: connector processed sample events");
    }
}
