package spike;

import com.fluxtion.compiler.Fluxtion;
import com.fluxtion.runtime.EventProcessor;
import com.fluxtion.runtime.annotations.OnEventHandler;

public class Spike2 {

    public static class Counter {
        private int count;

        @OnEventHandler
        public boolean onString(String s) {
            count++;
            System.out.println("handled " + s + " count=" + count);
            return true;
        }
    }

    public static void main(String[] args) {
        Counter counter = new Counter();
        EventProcessor<?> processor = Fluxtion.interpret(c -> c.addNode(counter));
        processor.init();
        processor.onEvent("a");
        processor.onEvent("b");
        System.out.println("SPIKE2 OK count=" + counter.count);
    }
}

