/** Net position per symbol, accumulated from every order {@link OrderIntake} accepts. */
public class PositionBook extends EventLogNode {

    private final OrderIntake orderIntake;

    @FluxtionIgnore
    private final Map<String, Integer> positionBySymbol = new LinkedHashMap<>();

    public PositionBook(OrderIntake orderIntake) {
        this.orderIntake = orderIntake;
    }

    @OnTrigger
    public boolean onOrder() {
        OrderEvent order = orderIntake.getLatestOrder();
        int position = positionBySymbol.merge(order.symbol(), order.signedQuantity(), Integer::sum);
        auditLog.info("symbol", order.symbol()).info("netPosition", position);
        return true;
    }

    public int positionFor(String symbol) {
        return positionBySymbol.getOrDefault(symbol, 0);
    }

    public Map<String, Integer> positions() {
        return Collections.unmodifiableMap(positionBySymbol);
    }
}

package com.example.riskflow.node;

import com.fluxtion.runtime.annotations.OnTrigger;
import com.fluxtion.runtime.annotations.builder.FluxtionIgnore;
import com.fluxtion.runtime.audit.EventLogNode;

import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.Map;

/**
 * Mark-to-market exposure: |net position| × mid, per symbol and in total.
 * Both parents are trigger parents — a new price revalues the book exactly as a new order does.
 */
public class ExposureCalculator extends EventLogNode {

    private final PositionBook positionBook;
    private final MarketData marketData;

    @FluxtionIgnore
    private final Map<String, Double> exposureBySymbol = new LinkedHashMap<>();
    private double totalExposure;

    public ExposureCalculator(PositionBook positionBook, MarketData marketData) {
        this.positionBook = positionBook;
        this.marketData = marketData;
    }

    @OnTrigger
    public boolean revalue() {
        exposureBySymbol.clear();
        totalExposure = 0;
        for (Map.Entry<String, Integer> position : positionBook.positions().entrySet()) {
            double mid = marketData.midFor(position.getKey());
            if (Double.isNaN(mid)) {
                continue;
            }
            double exposure = Math.abs(position.getValue()) * mid;
            exposureBySymbol.put(position.getKey(), exposure);
            totalExposure += exposure;
        }
        auditLog.info("totalExposure", totalExposure);
        return true;
    }

    public double exposureFor(String symbol) {
        return exposureBySymbol.getOrDefault(symbol, 0d);
    }

    public Map<String, Double> exposures() {
        return Collections.unmodifiableMap(exposureBySymbol);
    }

    public double getTotalExposure() {
        return totalExposure;
    }
}

package com.example.riskflow.node;

import com.fluxtion.runtime.annotations.OnTrigger;
import com.fluxtion.runtime.annotations.builder.AssignToField;
import com.fluxtion.runtime.annotations.builder.FluxtionIgnore;
import com.fluxtion.runtime.audit.EventLogNode;
import com.fluxtion.runtime.output.SinkPublisher;

import java.util.HashSet;
import java.util.Map;
import java.util.Set;

/**
 * Terminal node: publishes a line to the "alerts" sink when a limit is crossed, in either
 * direction. Only transitions are published — a book that stays over its limit does not
 * re-alert on every tick.
 */
public class RiskAlerter extends EventLogNode {

    private static final String TOTAL = "*TOTAL*";

    private final ExposureCalculator exposureCalculator;
    private final SinkPublisher<String> alertPublisher;
    private final double symbolLimit;
    private final double totalLimit;

    @FluxtionIgnore
    private final Set<String> breached = new HashSet<>();

    public RiskAlerter(ExposureCalculator exposureCalculator,
                       SinkPublisher<String> alertPublisher,
                       @AssignToField("symbolLimit") double symbolLimit,
                       @AssignToField("totalLimit") double totalLimit) {
        this.exposureCalculator = exposureCalculator;
        this.alertPublisher = alertPublisher;
        this.symbolLimit = symbolLimit;
        this.totalLimit = totalLimit;
    }

    @OnTrigger
    public boolean checkLimits() {
        for (Map.Entry<String, Double> exposure : exposureCalculator.exposures().entrySet()) {
            check(exposure.getKey(), exposure.getValue(), symbolLimit);
        }
        check(TOTAL, exposureCalculator.getTotalExposure(), totalLimit);
        return true;
    }

    private void check(String key, double exposure, double limit) {
        boolean overLimit = exposure > limit;
        if (overLimit && breached.add(key)) {
            publish("BREACH", key, exposure, limit);
        } else if (!overLimit && breached.remove(key)) {
            publish("CLEARED", key, exposure, limit);
        }
    }

    private void publish(String state, String key, double exposure, double limit) {
        String alert = "%-7s %-7s exposure=%,.2f limit=%,.2f".formatted(state, key, exposure, limit);
        auditLog.info("alert", alert);
        alertPublisher.publish(alert);
    }
}

